/// Workouts, routes, activity summaries (rings), ECG, audiograms, heartbeat series, state of mind, scored assessments, vision prescriptions, medication dose events. The three `HK...Type` identifiers without a public constant are listed as the runtime reports them.
pub const SPECIAL: &[&str] = &[
    "HKActivitySummaryTypeIdentifier",
    "HKDataTypeIdentifierAudiogram",
    "HKDataTypeIdentifierElectrocardiogram",
    "HKDataTypeIdentifierHeartbeatSeries",
    "HKDataTypeIdentifierStateOfMind",
    "HKDataTypeIdentifierUserAnnotatedMedicationConcept",
    "HKMedicationDoseEventTypeIdentifierMedicationDoseEvent",
    "HKScoredAssessmentTypeIdentifierGAD7",
    "HKScoredAssessmentTypeIdentifierPHQ9",
    "HKVisionPrescriptionTypeIdentifier",
    "HKWorkoutRouteTypeIdentifier",
    "HKWorkoutTypeIdentifier",
];

/// Every identifier of every family, in one iterator.
pub fn all() -> impl Iterator<Item = &'static str> {
    QUANTITY
        .iter()
        .chain(CATEGORY)
        .chain(CHARACTERISTIC)
        .chain(CORRELATION)
        .chain(DOCUMENT)
        .chain(CLINICAL)
        .chain(SPECIAL)
        .copied()
}

/// How many identifiers this build knows.
pub fn count() -> usize {
    all().count()
}

/// Lower-case, without the `HK` prefix and the `TypeIdentifier` / `DataTypeIdentifier`
/// infix, so that `HKQuantityTypeIdentifierBodyMass`, `quantityBodyMass` and
/// `bodyMass` (with kind `quantity`) all compare equal.
pub fn normalize(identifier: &str, kind: Option<&str>) -> String {
    let lower = identifier.trim().to_ascii_lowercase();
    let stripped = lower.strip_prefix("hk").unwrap_or(&lower);
    let stripped = stripped
        .replace("datatypeidentifier", "")
        .replace("typeidentifier", "");
    let families = [
        "quantity",
        "category",
        "characteristic",
        "correlation",
        "document",
        "clinical",
    ];
    if families.iter().any(|f| stripped.starts_with(f)) {
        return stripped;
    }
    match kind.map(|k| k.trim().to_ascii_lowercase()) {
        Some(k) if families.contains(&k.as_str()) => format!("{k}{stripped}"),
        _ => stripped,
    }
}

/// `true` when the identifier (in any of the spellings `normalize` accepts) is in
/// this build's list. Special sample types also match on their stem, so
/// `HKDataTypeIdentifierElectrocardiogram` and `HKElectrocardiogramType` agree.
pub fn is_known(identifier: &str, kind: Option<&str>) -> bool {
    let wanted = normalize(identifier, kind);
    if wanted.is_empty() {
        return false;
    }
    if all().any(|k| normalize(k, None) == wanted) {
        return true;
    }
    SPECIAL.iter().any(|s| {
        let stem = normalize(s, None);
        let stem = stem.trim_end_matches("type");
        !stem.is_empty()
            && (wanted.contains(stem) || stem.contains(wanted.trim_end_matches("type")))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_list_has_the_sdk_shape() {
        assert_eq!(QUANTITY.len(), 121);
        assert_eq!(CATEGORY.len(), 72);
        assert_eq!(CHARACTERISTIC.len(), 6);
        assert_eq!(CORRELATION.len(), 2);
        assert!(QUANTITY.contains(&"HKQuantityTypeIdentifierWorkoutEffortScore"));
        assert!(QUANTITY.contains(&"HKQuantityTypeIdentifierHeartRateRecoveryOneMinute"));
        assert!(CATEGORY.contains(&"HKCategoryTypeIdentifierSleepAnalysis"));
        assert!(SPECIAL.contains(&"HKWorkoutTypeIdentifier"));
        assert!(
            all().collect::<std::collections::BTreeSet<_>>().len() == count(),
            "no duplicates"
        );
    }

    #[test]
    fn spellings_normalize() {
        assert!(is_known("HKQuantityTypeIdentifierBodyMass", None));
        assert!(is_known("bodyMass", Some("quantity")));
        assert!(is_known(
            "HKCategoryTypeIdentifierSleepAnalysis",
            Some("category")
        ));
        assert!(is_known(
            "HKDataTypeIdentifierElectrocardiogram",
            Some("electrocardiogram")
        ));
        assert!(is_known("HKElectrocardiogramType", None));
        assert!(is_known("HKWorkoutTypeIdentifier", Some("workout")));
        assert!(!is_known(
            "HKQuantityTypeIdentifierSomethingNew",
            Some("quantity")
        ));
        assert!(!is_known("somethingNew", Some("quantity")));
        assert!(!is_known("", None));
    }
}
